"""Source-grounded Korean teaching content; equations are compiled to static HTML."""
import html

def p(s): return '<p>'+s+'</p>'
def m(s): return '<div class="math-block" data-tex="'+html.escape(s,quote=True)+'"></div>'
def c(title, body, kind='card'): return f'<div class="{kind}"><h3>{title}</h3>{body}</div>'
def n(title,body): return c('뉴비 모드 · '+title,p('<span class="evidence-label">편집자 보강</span>')+body,'card newbie-note')
def correction(s): return c('원본 확인 · 교정',p(s),'callout')
def steps(items): return '<ol class="solution-steps">'+''.join('<li>'+x+'</li>' for x in items)+'</ol>'
PAGES=[]
def add(title,body,role='개념과 해설'): PAGES.append(dict(title=title,body=body,role=role))

add('Fourier series(푸리에 급수): 단원 표지',c('자료 안내',p('Arshad Afzal의 Fourier series 강의자료입니다. 원본의 순서대로 inner product(내적), Fourier series(푸리에 급수), eigenfunction expansion(고유함수 전개)을 연결합니다. 수업 날짜와 주차는 자료에 기재되어 있지 않습니다.'),'quiet-card'),'표지')
add('Inner product(내적): 성분을 곱해 더하는 이유',
c('내적은 두 벡터의 성분이 얼마나 같은 방향으로 놓였는지 측정합니다.',p('실수 벡터의 inner product(내적)는 대응하는 성분을 곱해서 더한 실수입니다. 두 벡터가 모두 0이 아닐 때 내적이 0이면 orthogonal(직교)하다고 합니다. 한 성분의 곱이 0이어야 하는 것이 아니라, 모든 곱의 합이 0이어야 합니다.')+m(r'\langle \mathbf{x},\mathbf{y}\rangle=\mathbf{x}^{T}\mathbf{y}=\sum_{j=1}^{d}x_jy_j')+p('뒤에서 함수의 곱을 적분하는 공식은 바로 이 계산을 연속적인 입력값 전체로 확장한 것입니다.'))+
c('원본 계산식의 합은 0이므로 직교합니다.',m(r'1\cdot4+(-2)\cdot1+3\cdot(-2)+(-1)\cdot(-4)=4-2-6+4=0')+p('마지막 곱은 음수×음수이므로 +4입니다. 아래 계산식에 사용된 벡터 x=(1,−2,3,−1), y=(4,1,−2,−4)는 orthogonal(직교)합니다.'))+
c('원본 표기 대조 · 세로 벡터와 계산식을 구별합니다.',p('원본 위쪽 세로 벡터에는 y의 마지막 성분이 +4, 아래 계산식에는 −4로 적혀 있습니다. +4를 사용한 별도 계산은 −8이지만, 이것을 아래 계산식의 합이라고 읽으면 안 됩니다. 이 해설은 아래 계산식의 −4를 기준으로 직교 예제를 설명합니다.'),'callout')+
n('고등학교 벡터에서 출발하기',p('평면에서 x=(2,1), y=(1,−2)라면 내적은 2×1+1×(−2)=0입니다. 내적 공식 x·y=|x||y|cosθ에서 두 길이가 0이 아니므로 cosθ=0, 즉 두 방향은 수직입니다. 4차원에서는 그림을 그리기 어렵지만 같은 곱셈·덧셈 규칙을 사용합니다.')+p('T는 transpose(전치)를 뜻합니다. 세로로 적힌 숫자를 가로로 눕혀 행렬 곱을 쓰는 표기이며, 여기서는 각 자리끼리 곱하는 계산과 같습니다.')))
add('Fourier expansion(푸리에 전개): 좌표를 내적으로 구합니다.',
c('Orthonormal basis(정규직교기저)가 있으면 좌표가 바로 내적입니다.',p('Basis(기저)는 벡터를 조립하는 독립적인 기준 방향입니다. 서로 직교하고 각 길이가 1이면 orthonormal(정규직교)이라고 합니다. 벡터 x를 각 기준 방향에 projection(정사영)해서 얻은 값이 그 방향의 coefficient(계수)입니다.')+m(r'\mathbf{x}=\sum_{j=1}^{d}\langle \mathbf{u}_j,\mathbf{x}\rangle\mathbf{u}_j')+p('기저가 직교하기만 하고 길이가 1이 아니라면 계수는 ⟨uⱼ,x⟩/⟨uⱼ,uⱼ⟩입니다. 이 분모가 나중에 푸리에 계수의 1/π, 1/L로 나타납니다.'))+
correction('원본은 Rⁿ의 유한 기저를 설명하면서 마지막 합의 상한을 ∞로 씁니다. 유한차원 설명에서는 기저 개수까지 합해야 합니다. 함수 공간의 무한급수는 다음 페이지의 별도 확장입니다.')+
n('좌표 (3,2)는 이미 작은 푸리에 전개입니다.',p('(3,2)=3(1,0)+2(0,1)입니다. 수평 방향을 얼마나 넣을지 3, 수직 방향을 얼마나 넣을지 2가 알려줍니다. 이제 기준 방향 대신 sin x, cos x 같은 기본 그래프를 사용하면 “함수의 좌표”라는 아이디어가 됩니다.')+p('길이가 2인 기준 u=(2,0)로 (3,2)의 수평 부분을 만들려면 1.5u여야 합니다. 내적 6만 쓰지 않고 6/4=1.5로 나누는 이유도 이 예에서 보입니다.')))
add('함수의 inner product(내적): 합을 적분으로 바꿉니다.',
c('함수도 여러 기준 함수의 합으로 분해할 수 있습니다.',p('실수 함수에 대해 구간 [a,b]의 inner product(내적)를 곱의 적분으로 정합니다. Orthogonality(직교성)는 이 적분이 0이라는 뜻입니다. 완전한 정규직교 함수계를 갖추면 함수의 좌표를 내적으로 구해 전개할 수 있습니다.')+m(r'\langle f,g\rangle=\int_a^b f(x)g(x)\,dx,\qquad a_j=\langle f,\phi_j\rangle')+m(r'f\sim\sum_{j=1}^{\infty}a_j\phi_j')+p('여기서 ∼는 푸리에 전개에 대응한다는 뜻입니다. 원함수와 언제, 어떤 의미로 같아지는지는 convergence(수렴)와 completeness(완비성)를 따로 확인합니다. 직교성만으로 모든 함수의 복원이 보장되지는 않습니다.'))+
correction('원본의 f(x)g(x)dt는 변수 표기가 섞였습니다. x로 쓴 함수의 적분은 dx로 통일합니다.')+
n('적분을 “아주 촘촘한 합”으로 읽기',p('입력 x를 여러 점으로 잘라 각 점에서 f(x)g(x)를 계산하고, 작은 간격 Δx를 곱해 더합니다. 간격을 계속 줄인 극한이 ∫f(x)g(x)dx입니다. 적분은 넓이와 연결되지만, 그래프 아래쪽은 음수로 계산하는 signed area(부호 있는 넓이)입니다.')+p('따라서 두 함수가 모든 점에서 0이어야 직교하는 것이 아닙니다. 양수로 쌓인 부분과 음수로 쌓인 부분이 정확히 상쇄되어도 내적은 0입니다.')))
add('Periodic function(주기함수): 같은 모양을 반복합니다.',
c('한 주기를 알면 전체 그래프가 정해집니다.',p('양수 T에 대해 f(x+T)=f(x)가 모든 x에서 성립하면 T는 period(주기)입니다. 존재하는 최소 양의 주기를 fundamental period(기본주기)라고 합니다. Fourier series(푸리에 급수)는 주기 신호를 기본 진동과 그 정수배 주파수의 harmonics(고조파)로 분해합니다.')+m(r'f(x+T)=f(x),\qquad \omega_0=\frac{2\pi}{T}')+p('상수함수처럼 최소 양의 주기가 없는 경우도 있습니다. 모든 함수를 아무 주기로 반복시킬 수 있다는 뜻은 아니며, 유한 구간의 함수를 주기적으로 연장하는 일과 원래부터 주기적인 함수인 것은 구별해야 합니다.'))+
n('sin x와 sin 3x는 무엇이 다른가요?',p('sin x는 x가 2π 늘어날 때 한 바퀴를 돕니다. sin 3x는 괄호 안이 세 배 빠르게 변하므로 2π/3만 늘어도 한 바퀴를 돕니다. a sin 3x에서 a는 세로 크기, 3은 진동의 빠르기입니다. 여러 빠르기의 파동을 더하면 매끈한 사인파만으로도 각진 모양에 가까워질 수 있습니다.')))
add('삼각함수의 직교성 ①: sine(사인)와 cosine(코사인)',
c('사인과 코사인의 곱은 대칭 구간에서 상쇄됩니다.',p('n,m이 양의 정수일 때 sin(nx)는 odd function(홀함수), cos(mx)는 even function(짝함수)입니다. 그 곱은 홀함수이므로 [−π,π]에서 적분하면 0입니다. n=m일 때도 같은 결론입니다.')+m(r'\int_{-\pi}^{\pi}\sin(nx)\cos(mx)\,dx=0')+m(r'\sin A\cos B=\tfrac12\{\sin(A+B)+\sin(A-B)\}')+p('Product-to-sum identity(곱을 합으로 바꾸는 공식)로도 증명할 수 있습니다. n=m이면 sin((n−m)x)=0을 먼저 처리해야 하며, n−m으로 나누는 식에 그대로 대입하면 안 됩니다.'))+
correction('원본의 곱-합 변환에서 두 번째 sin의 인수는 (n−m)x입니다. (n+m)x가 두 번 적힌 부분은 교정합니다.')+
n('좌우를 접으면 왜 0인가요?',p('h(x)=sin(nx)cos(mx)라 합시다. h(−x)=−h(x)이므로 오른쪽에서 넓이 +3만큼 생기면 왼쪽에서는 −3만큼 생깁니다. 두 넓이를 합치면 0입니다. 길고 복잡한 적분보다 먼저 그래프의 대칭을 확인하는 이유입니다.')))
add('삼각함수의 직교성 ②: 같은 종류의 주파수 구분',
c('서로 다른 주파수는 0, 같은 주파수의 제곱은 π입니다.',m(r'\int_{-\pi}^{\pi}\cos(nx)\cos(mx)\,dx=\begin{cases}0&n\ne m\\\pi&n=m\end{cases}')+m(r'\int_{-\pi}^{\pi}\sin(nx)\sin(mx)\,dx=\begin{cases}0&n\ne m\\\pi&n=m\end{cases}')+p('위 식은 n,m≥1에 대한 것입니다. Constant function(상수함수) 1의 제곱 적분은 2π입니다. 따라서 이 함수계는 orthogonal(직교)하지만 그대로는 orthonormal(정규직교)이 아닙니다.')+m(r'\sin A\sin B=\tfrac12[\cos(A-B)-\cos(A+B)]')+m(r'\cos A\cos B=\tfrac12[\cos(A-B)+\cos(A+B)]'))+
correction('원본 사인 곱-합 공식의 부호·순서는 cos(A−B)−cos(A+B)로 읽어야 합니다. n=m일 때에는 위의 다른 주파수용 분모를 쓰지 말고 제곱 공식으로 계산합니다.')+
n('같은 파동을 곱할 때는 음수 넓이가 사라집니다.',p('sin x가 양수이든 음수이든 sin²x는 0 이상입니다. sin²x=(1−cos 2x)/2이므로 한 주기 평균은 1/2입니다. 구간 길이 2π를 곱하면 적분값이 π가 됩니다. 반면 1²은 항상 1이라 평균도 1, 적분값도 2π입니다.')))
add('기본 Fourier series(푸리에 급수)와 세 종류의 계수',
c('이 노트는 원본처럼 상수항을 a₀로 씁니다.',m(r'f(x)\sim a_0+\sum_{n=1}^{\infty}\bigl[a_n\cos(nx)+b_n\sin(nx)\bigr]')+m(r'a_0=\frac1{2\pi}\int_{-\pi}^{\pi}f(x)\,dx')+m(r'a_n=\frac1\pi\int_{-\pi}^{\pi}f(x)\cos(nx)\,dx,\quad n\ge1')+m(r'b_n=\frac1\pi\int_{-\pi}^{\pi}f(x)\sin(nx)\,dx,\quad n\ge1')+p('a₀는 mean value(평균값), aₙ과 bₙ은 각 cosine(코사인)·sine(사인) 성분의 크기입니다. 다른 교재의 a₀/2 표기와 혼용하면 상수항이 두 배 또는 절반으로 틀립니다. 이 노트의 a₀는 그 교재 a₀의 절반입니다.'))+
n('Σ부터 읽는 연습',p('Σₙ₌₁∞는 n에 1,2,3,…을 대입한 항들을 계속 더한다는 기호입니다. 앞부분만 펼치면 a₀+a₁cos x+b₁sin x+a₂cos 2x+b₂sin 2x+…입니다. 계수는 x에 따라 변하지 않는 숫자이고, 각 파동 앞의 조절 손잡이라고 생각하면 됩니다.')+p('예를 들어 f(x)=2+3cos x−sin 2x는 이미 분해되어 있습니다. a₀=2, a₁=3, b₂=−1이고 나머지는 0입니다. 굳이 모든 적분을 다시 계산할 필요는 없습니다.')))
add('a₀ 유도: 한 주기 평균만 남기기',
c('양변을 적분하면 모든 진동 성분이 사라집니다.',steps([p('먼저 finite partial sum(유한 부분합)을 생각합니다. 1 이상의 정수 n에 대해 cos(nx), sin(nx)는 한 주기 동안 적분값이 0입니다.'),m(r'\int_{-\pi}^{\pi}f(x)\,dx=2\pi a_0'),p('구간 길이 2π로 나누면 평균값이 됩니다.')+m(r'a_0=\frac1{2\pi}\int_{-\pi}^{\pi}f(x)\,dx')])+p('무한합의 항별 적분을 엄밀하게 정당화하려면 적절한 수렴 조건이 필요합니다. 계수 공식 자체는 내적과 projection(정사영)으로 정의할 수 있습니다.'))+
correction('원본에서 sin(nx)의 부정적분은 −cos(nx)/n입니다. 적분 구간 전체에서는 0이라 최종 a₀ 공식은 바뀌지 않습니다.')+
n('평균값 공식은 숫자의 평균과 같습니다.',p('숫자 다섯 개의 합을 5로 나누면 평균입니다. 함수는 입력값이 연속적으로 무수히 많으므로 합을 적분으로, 개수를 구간 길이로 바꿉니다. f(x)=3이라면 ∫₋ππ3dx=6π이고 6π/(2π)=3입니다.')))
add('aₙ 유도: 원하는 cosine(코사인) 성분만 골라내기',
c('cos(mx)를 곱한 뒤 적분합니다.',p('고정한 m≥1에 대해 모든 항에 cos(mx)를 곱합니다. 상수항의 적분은 0, 모든 sine(사인) 교차항도 0, n≠m인 cosine(코사인) 교차항도 0입니다. 오직 aₘcos²(mx)만 남습니다.')+m(r'\int_{-\pi}^{\pi}f(x)\cos(mx)\,dx=a_m\int_{-\pi}^{\pi}\cos^2(mx)\,dx=\pi a_m')+p('양변을 π로 나누고 m을 n으로 바꾸면 앞의 계수 공식입니다. m은 검사하려는 주파수, n은 합 안에서 움직이는 번호였을 뿐입니다.'))+
correction('원본의 “=0, m≠n”은 각각의 교차항에 대한 성질입니다. f 전체와 cos(mx)의 내적이 언제나 0이라는 뜻으로 읽으면 안 됩니다.')+
n('숫자를 대입해 추출 과정을 보기',p('f(x)=2+3cos x−sin 2x에서 cos x를 곱하면 2cos x+3cos²x−sin 2x cos x가 됩니다. 첫째와 셋째 적분은 0이고 둘째는 3π입니다. 이를 π로 나누면 정확히 3이 나옵니다. 섞인 함수에서 특정 성분만 꺼내는 장치가 직교성입니다.')))
add('bₙ 유도: 원하는 sine(사인) 성분만 골라내기',
c('sin(mx)를 곱한 뒤 같은 계산을 합니다.',m(r'\int_{-\pi}^{\pi}f(x)\sin(mx)\,dx=b_m\int_{-\pi}^{\pi}\sin^2(mx)\,dx=\pi b_m')+p('상수×사인, 코사인×사인, 서로 다른 주파수의 사인×사인은 모두 적분값이 0입니다. sin²(mx)의 적분값 π로 나누면 bₘ을 얻습니다. 이 방법은 나중에 어떤 orthogonal basis(직교기저)를 사용하더라도 동일합니다.')+m(r'\text{coefficient}=\frac{\langle f,\text{basis function}\rangle}{\langle\text{basis function},\text{basis function}\rangle}'))+
n('왜 적분 뒤에 다시 나누나요?',p('sin x 자체도 길이가 1인 기준이 아닙니다. 제곱해서 적분한 값이 π이므로, 원하는 계수보다 π배 큰 측정값이 나옵니다. 자 눈금이 π배 확대되어 있다고 생각하고 다시 π로 나누면 됩니다. 부호가 음수인 계수는 그 파동을 위아래 반전해 넣는다는 뜻입니다.')))
add('예제: rectangular wave(사각파)의 전체 풀이',
c('문제 읽기',p('주기 2π, −π&lt;x&lt;0에서 −k, 0&lt;x&lt;π에서 k인 rectangular wave(사각파)를 전개합니다. k는 상수입니다. 원점 대칭인 odd function(홀함수)이므로 a₀=aₙ=0입니다.'))+
c('bₙ을 직접 계산합니다.',steps([m(r'b_n=\frac1\pi\left[\int_{-\pi}^{0}(-k)\sin(nx)\,dx+\int_0^{\pi}k\sin(nx)\,dx\right]'),p('두 구간의 곱이 대칭이므로 오른쪽 적분의 두 배로 줄입니다.')+m(r'b_n=\frac{2k}{\pi}\int_0^\pi\sin(nx)\,dx=\frac{2k}{n\pi}[1-\cos(n\pi)]'),p('cos(nπ)=(−1)ⁿ이므로 짝수 n에는 0, 홀수 n에는 4k/(nπ)가 됩니다.')+m(r'f(x)\sim\frac{4k}{\pi}\sum_{j=0}^{\infty}\frac{\sin((2j+1)x)}{2j+1}')])+p('불연속점 x=jπ에서는 급수의 합이 좌우 평균 0입니다. 원래 함수에 어떤 점 값을 따로 지정하더라도 이 Fourier limit(푸리에 극한)은 변하지 않습니다.'))+
n('짝수 번호가 사라지는 계산',p('n=1이면 1−(−1)=2라서 b₁=4k/π입니다. n=2이면 1−1=0입니다. n=3이면 다시 2라서 b₃=4k/(3π)입니다. 따라서 sin x, sin 3x, sin 5x만 남습니다. “홀함수라서 홀수 번호만 남는다”는 일반 법칙은 아닙니다. 홀함수이면 사인만 남고, 이 사각파의 추가 대칭 때문에 짝수 번호까지 사라집니다.')),'예제 · 편집자 풀이')
add('Partial sum(부분합): 몇 항까지 더했는지 구별합니다.',
c('원본의 S₁, S₂, S₃는 0이 아닌 사인 항을 세는 표기입니다.',m(r'S_M(x)=\frac{4k}{\pi}\sum_{j=0}^{M-1}\frac{\sin((2j+1)x)}{2j+1}')+p('M=1이면 sin x까지, M=2이면 sin 3x까지, M=3이면 sin 5x까지 더합니다. 반면 원본 MATLAB의 for n=1:3은 주파수 번호 1,2,3을 순회하므로 0이 아닌 항은 sin x와 sin 3x 두 개뿐입니다.')+p('세 개의 0이 아닌 항을 그리려면 반복 범위를 n=[1,3,5] 또는 n=1:2:5로 잡아야 합니다.'))+
c('편집자 보강 · 직접 더해 보는 사각파',p('슬라이더는 0이 아닌 홀수차 항의 개수를 조절합니다. 검은 선은 목표 사각파(k=1), 크림슨 선은 부분합입니다.')+'<div class="wave-demo"><label for="term-count">더할 항 수 <output id="term-output" for="term-count">3</output></label><input id="term-count" type="range" min="1" max="50" value="3"><canvas id="fourier-canvas" width="960" height="400" role="img" aria-label="사각파와 푸리에 부분합 비교">부분합은 sin x, sin 3x, sin 5x를 차례로 더해 사각파에 가까워집니다.</canvas><p id="wave-caption">3항: 최대 주파수는 5차입니다.</p></div>')+
n('곡선 세 개를 더하는 법',p('같은 x에서 첫 곡선의 높이, 두 번째 높이, 세 번째 높이를 더해 새 높이를 찍습니다. 그래프를 옆으로 이어 붙이는 것이 아닙니다. 낮은 주파수는 큰 윤곽을, 높은 주파수는 급격한 변화를 더 자세히 만듭니다.')))
add('Convergence(수렴): 점프에서는 좌우 평균으로 갑니다.',
c('함수의 점 값과 급수의 극한은 다를 수 있습니다.',p('이 자료의 조각별 매끄러운 함수들에는, 한 주기에서 유한 개의 조각을 갖고 각 조각의 함수와 도함수가 경계까지 적절한 유한 일방극한을 가지는 충분조건을 적용할 수 있습니다. 연속점에서는 f(x), jump discontinuity(점프 불연속점)에서는 좌우 극한의 평균으로 수렴합니다.')+m(r'S(x_0)=\frac{f(x_0^-)+f(x_0^+)}{2}')+p('원본 예제에서 x=1 왼쪽은 x², 오른쪽은 x/2이므로 왼쪽 극한은 1, 오른쪽 극한은 1/2입니다. 따라서 S(1)=3/4입니다. 함수 정의 자체의 f(1)=1/2와 구별하십시오. 이 예제는 점프 근방을 보여주며, 이 조각식을 실수 전체에서 그대로 쓰면 주기함수가 되지는 않습니다.'))+
correction('“piecewise continuous(조각별 연속)이면 항상 점별 수렴”이라는 원문은 조건이 부족합니다. 본문은 조각별 매끄러움 등 충분조건을 함께 명시합니다. 참고: <a href="https://dlmf.nist.gov/1.8#ii">NIST DLMF §1.8(ii)</a>.')+
n('왼쪽 값과 오른쪽 값을 따로 계산하기',p('x=0.999…를 x²에 넣으면 1에 가까워집니다. x=1.000…를 x/2에 넣으면 0.5에 가까워집니다. 이 두 값의 중간이 (1+0.5)/2=0.75입니다. 점프 한 점의 높이를 바꿔도 적분값은 변하지 않으므로 Fourier coefficient(푸리에 계수)도 변하지 않습니다.')))
add('Gibbs phenomenon(깁스 현상): 항을 늘려도 꼭대기가 남습니다.',
c('전체 근사가 좋아지는 것과 점프 근처의 최대 오차는 다릅니다.',p('Jump discontinuity(점프 불연속점) 근처에는 overshoot(초과 진동)가 발생합니다. 더 많은 항을 더하면 진동이 집중되는 영역은 좁아지지만, 점프 크기에 대한 최대 overshoot(초과량)는 0으로 사라지지 않습니다. 이는 계산 프로그램의 고장이 아니라 Fourier partial sum(푸리에 부분합)의 성질입니다.')+p('점프에서 멀리 떨어진 고정된 점의 수렴, 점프점 자체의 평균값 수렴, 점프 근처에서 위치가 이동하는 최대 오차를 서로 구별해야 합니다.'))+
n('폭이 줄어드는 것과 높이가 줄어드는 것은 별개입니다.',p('아주 좁지만 높은 바늘 모양의 오차를 생각하십시오. 폭이 줄면 전체 오차 넓이는 작아질 수 있어도 가장 높은 지점은 남습니다. 앞의 슬라이더에서 항을 늘려 보면 평평한 부분은 좋아지고, 점프 옆 봉우리는 더 좁은 곳에 모입니다. 이 때문에 평균제곱 오차가 줄어드는 사실과 모순되지 않습니다.')))
add('주기 바꾸기 ①: 2π에서 2L로 좌표를 늘입니다.',
c('기본 파동의 괄호 안을 πx/L로 바꿉니다.',p('원래 좌표 u∈[−L,L]를 표준 각도 θ=πu/L로 바꾸면 양 끝이 −π,π에 대응합니다. 따라서 한 주기의 길이가 2L인 기본 사인파는 sin(πu/L)입니다.')+m(r'\theta=\frac{\pi}{L}u,\qquad d\theta=\frac{\pi}{L}\,du')+m(r'a_0=\frac1{2\pi}\int_{-L}^{L}f(u)\frac{\pi}{L}\,du=\frac1{2L}\int_{-L}^{L}f(u)\,du')+p('원본은 같은 f 기호로 바꾸기 전후 함수를 적습니다. 엄밀히는 g(θ)=f(Lθ/π)로 구별하면 변수 혼동을 피할 수 있습니다.'))+
n('길이가 10인 파동을 만들기',p('T=10이면 L=5입니다. sin x를 그대로 쓰면 주기가 약 6.28이므로 틀립니다. sin(πx/5)는 x가 10 늘 때 괄호 안이 2π 늘어나므로 정확히 길이 10을 반복합니다. L은 전체 주기가 아니라 그 절반입니다.')))
add('주기 바꾸기 ②: 일반 주기의 계수 공식',
c('전체 주기 2L와 반주기 L을 분리해서 기억합니다.',m(r'f(x)\sim a_0+\sum_{n=1}^{\infty}\left[a_n\cos\frac{n\pi x}{L}+b_n\sin\frac{n\pi x}{L}\right]')+m(r'a_0=\frac1{2L}\int_{-L}^{L}f(x)\,dx')+m(r'a_n=\frac1L\int_{-L}^{L}f(x)\cos\frac{n\pi x}{L}\,dx')+m(r'b_n=\frac1L\int_{-L}^{L}f(x)\sin\frac{n\pi x}{L}\,dx')+p('원본의 변수 치환 중간 줄에서 dθ=(π/L)du여야 합니다. 추가 u를 곱하는 표기는 제외합니다. 한 주기 전체라면 [−L,L] 대신 다른 시작점에서 길이 2L인 구간을 적분해도 됩니다.'))+
n('공식 사용 전 네 칸 채우기',steps([p('주기 T를 확인합니다.'),p('L=T/2를 구합니다.'),p('파동의 괄호를 nπx/L로 씁니다.'),p('상수항 앞에는 1/(2L), 나머지 계수 앞에는 1/L을 씁니다.')])+p('예를 들어 T=4이면 L=2, 사인 괄호는 nπx/2입니다. 적분 구간은 −2부터 2까지입니다.')))
add('Even function(짝함수): cosine series(코사인 급수)',
c('f(−x)=f(x)이면 사인 계수가 모두 0입니다.',p('짝함수와 사인의 곱은 odd function(홀함수)이므로 적분값 0입니다. 짝함수와 코사인의 곱은 짝함수이므로 전체 적분은 오른쪽 절반의 두 배입니다.')+m(r'b_n=0,\qquad a_0=\frac1L\int_0^L f(x)\,dx')+m(r'a_n=\frac2L\int_0^L f(x)\cos\frac{n\pi x}{L}\,dx')+p('그래프의 높이가 모두 양수라고 해서 짝함수가 되는 것은 아닙니다. 반드시 y축 좌우의 대응점이 같은지 검사합니다.'))+
n('짝×짝, 짝×홀을 숫자 대신 부호로 보기',p('짝함수는 x를 −x로 바꿔도 +, 홀함수는 −가 붙습니다. 짝×짝은 (+)(+)=+, 짝×홀은 (+)(−)=−입니다. 예를 들어 x²cos x는 짝함수라 적분을 두 배로 줄이고, x²sin x는 홀함수라 적분이 0입니다.')))
add('Odd function(홀함수): sine series(사인 급수)',
c('f(−x)=−f(x)이면 상수항과 코사인이 사라집니다.',m(r'a_0=a_n=0,\qquad b_n=\frac2L\int_0^L f(x)\sin\frac{n\pi x}{L}\,dx')+p('홀함수와 코사인의 곱은 홀함수입니다. 홀함수와 사인의 곱은 even function(짝함수)이므로 두 배 적분을 적용합니다. n이 홀수인지 짝수인지와는 별개의 대칭 성질입니다.')+p('원본 마지막 유도 줄의 g(x)는 앞서 정의한 h(x)=f(x)sin(nπx/L)를 가리켜야 합니다.'))+
n('음수×음수는 양수입니다.',p('f(x)=x라면 왼쪽에서 x도 음수이고 sin x도 음수인 구간이 있어 곱은 양수입니다. 일반적인 대칭식으로는 f(−x)sin(−nπx/L)=(−f(x))(−sin(nπx/L))=f(x)sin(nπx/L)입니다. 그래서 왼쪽을 버리는 것이 아니라 오른쪽의 두 배로 합치는 것입니다.')))
add('Linearity(선형성): 이미 구한 급수를 재사용합니다.',
c('같은 주기와 기저를 쓰는 함수는 계수끼리 더할 수 있습니다.',p('g=cf₁+f₂라면 g의 모든 Fourier coefficient(푸리에 계수)는 f₁의 계수에 c를 곱한 뒤 f₂의 대응 계수를 더한 것입니다. 이는 적분의 linearity(선형성)에서 바로 나옵니다.')+m(r'a_n[g]=c\,a_n[f_1]+a_n[f_2],\qquad b_n[g]=c\,b_n[f_1]+b_n[f_2]')+p('a₀에도 같은 규칙이 적용됩니다. 서로 주기가 다르면 먼저 공통 주기와 동일한 주파수 번호 체계로 맞춰야 합니다. 일반적으로 함수의 곱에는 이 단순한 규칙을 적용할 수 없습니다.'))+
correction('원본의 aₙ,bₙ 유도 중간 줄에 들어간 1/(2L)은 1/L이어야 합니다. 마지막 선형성 결론은 맞습니다.')+
n('x+π를 한번에 보지 말고 나누기',p('x는 홀함수라 사인만 필요합니다. π는 상수라 a₀=π만 필요합니다. 따라서 톱니파 x+π의 계산은 x의 사인 계수에 평균값 π를 붙이는 일이 됩니다. 뒤의 Problem 2에서 그대로 사용합니다.')))

add('Complex form(복소수 형식) ①: 두 파동을 지수로 묶습니다.',
c('Euler’s formula(오일러 공식)로 같은 함수를 다시 표기합니다.',m(r'e^{i\theta}=\cos\theta+i\sin\theta,\qquad i^2=-1')+m(r'\cos\theta=\frac{e^{i\theta}+e^{-i\theta}}2,\qquad\sin\theta=\frac{e^{i\theta}-e^{-i\theta}}{2i}')+p('두 식을 aₙcos(nx)+bₙsin(nx)에 대입하고 eⁱⁿˣ와 e⁻ⁱⁿˣ의 계수를 각각 모읍니다. 1/i=−i를 이용하면 다음 결과가 나옵니다.')+m(r'c_0=a_0,\quad c_n=\frac{a_n-ib_n}{2},\quad c_{-n}=\frac{a_n+ib_n}{2}\quad(n\ge1)'))+
correction('원본의 대입 과정에서 사인 분자의 두 지수 사이 부호는 +가 아니라 −입니다. 뒤의 cₙ, c₋ₙ 공식은 올바릅니다.')+
n('복소수가 나와도 함수가 갑자기 다른 것이 되지는 않습니다.',p('Complex number(복소수) a+bi는 실수 부분 a와 허수 부분 b를 함께 기록하는 표기입니다. 고등학교에서 배운 i²=−1을 그대로 씁니다. Euler’s formula(오일러 공식)의 증명은 이 노트 범위를 넘지만, 여기서는 사인·코사인을 묶는 변환 공식으로 사용해도 계수 계산을 따라갈 수 있습니다.')+p('cos x=(eⁱˣ+e⁻ⁱˣ)/2에서 두 지수의 허수 부분 +i sin x와 −i sin x가 서로 없어집니다. “복소수로 썼으니 출력도 반드시 복소수”라는 뜻이 아닙니다.')))
add('Complex form(복소수 형식) ②: 계수 하나로 통일합니다.',
c('양수·음수 주파수를 하나의 합에 넣습니다.',m(r'f(x)\sim\sum_{n=-\infty}^{\infty}c_ne^{inx},\qquad c_n=\frac1{2\pi}\int_{-\pi}^{\pi}f(x)e^{-inx}\,dx')+p('n은 0과 음의 정수를 포함하는 모든 정수입니다. 실제 값이 실수인 함수에서는 conjugate symmetry(켤레 대칭) c₋ₙ=conj(cₙ)가 성립합니다. 복소 계수의 위상 정보까지 보존해야 원래 파동을 복원할 수 있습니다.')+m(r'\int_{-\pi}^{\pi}e^{i(n-m)x}\,dx=\begin{cases}2\pi&n=m\\0&n\ne m\end{cases}'))+
correction('원본 cₙ,c₋ₙ 유도에는 1/2와 1/(2π)가 중복되어 있습니다. 올바른 대입은 (1/2)[(1/π)∫f cos−i(1/π)∫f sin]입니다. 최종 상자 안의 1/(2π) 공식은 맞습니다.')+
n('왜 지수에 마이너스가 붙나요?',p('원하는 m번째 파동 eⁱᵐˣ를 검사하려면 e⁻ⁱᵐˣ를 곱합니다. 지수법칙으로 eⁱⁿˣe⁻ⁱᵐˣ=eⁱ⁽ⁿ⁻ᵐ⁾ˣ가 됩니다. 번호가 같으면 e⁰=1이 남고, 다르면 한 주기 동안 상쇄됩니다. Inner product(내적)에서 “목표 성분만 남긴다”는 원리는 그대로입니다.')))
add('Time-periodic signal(시간 주기 신호): T와 ω₀',
c('상수항·실수 계수·복소 계수의 앞 계수를 구별합니다.',m(r'\omega_0=\frac{2\pi}{T},\quad f(t)\sim a_0+\sum_{n=1}^{\infty}[a_n\cos(n\omega_0t)+b_n\sin(n\omega_0t)]')+m(r'a_0=\frac1T\int_{-T/2}^{T/2}f(t)\,dt')+m(r'a_n=\frac2T\int_{-T/2}^{T/2}f(t)\cos(n\omega_0t)\,dt')+m(r'b_n=\frac2T\int_{-T/2}^{T/2}f(t)\sin(n\omega_0t)\,dt')+m(r'c_n=\frac1T\int_{-T/2}^{T/2}f(t)e^{-in\omega_0t}\,dt'))+
correction('원본 p.23의 aₙ,bₙ 앞 1/T는 2/T로 교정합니다. a₀와 cₙ의 1/T는 맞습니다. p.17의 L=T/2를 대입하거나 f(t)=cos(ω₀t)에서 a₁=1인지 확인하면 검증할 수 있습니다.')+
n('초와 라디안을 연결하기',p('Period(주기) T=2초이면 2초에 한 바퀴이므로 frequency(주파수)는 1/T=0.5 Hz입니다. 한 바퀴가 2π rad이므로 angular frequency(각주파수)는 ω₀=π rad/s입니다. 주파수 0.5와 각주파수 π는 단위와 의미가 다르며, 2π를 곱해 연결합니다.')))
add('Frequency spectrum(주파수 스펙트럼): 사각 펄스의 계수',
c('폭 1/2, 높이 1, 주기 1인 펄스를 풉니다.',p('−1/4&lt;x&lt;1/4에서 1이고, 나머지 한 주기 구간에서는 0입니다. Fundamental angular frequency(기본 각주파수)는 2π입니다. 함수가 0인 구간의 적분은 사라집니다.')+steps([m(r'c_0=\int_{-1/4}^{1/4}1\,dx=\frac12'),m(r'c_n=\int_{-1/4}^{1/4}e^{-2\pi inx}\,dx=\left[\frac{e^{-2\pi inx}}{-2\pi in}\right]_{-1/4}^{1/4}\quad(n\ne0)'),m(r'c_n=\frac{\sin(n\pi/2)}{n\pi}\quad(n\ne0)')])+p('따라서 c₁=1/π, c₂=0, c₃=−1/(3π)입니다. 각주파수로 나타낸 spectrum(스펙트럼)은 (2πn,|cₙ|)에 선을 그립니다. 원본 그림의 가로축은 각주파수가 아니라 정수 번호 n입니다. c₃은 음수지만 스펙트럼의 크기는 1/(3π)입니다.'))+
c('0번 계수와 파동의 크기',p('원본 그래프에는 |c₀|=1/2가 이미 표시되어 있습니다. 위 계산은 그 값의 유도 과정입니다. n=0을 분모 n이 있는 공식에 그대로 넣으면 0/0입니다. 평균값 적분으로 따로 계산해야 합니다. 실수 even function(짝함수)이므로 bₙ=0이고 aₙ=2cₙ(n≥1)입니다. 이 양측 복소 스펙트럼 |cₙ|과 실수 cosine(코사인) 진폭 aₙ을 혼동하지 마십시오.'))+
n('스펙트럼을 막대그래프로 읽기',p('가로축은 “얼마나 빠르게 흔들리는가”, 세로축은 “그 성분이 얼마나 큰가”입니다. 0번 막대는 흔들리지 않는 평균값 1/2입니다. 계수의 절댓값만 그리면 부호나 phase(위상)는 사라지므로, 이 그림 하나만으로 원 신호를 항상 복원할 수는 없습니다.')),'예제 · 편집자 풀이')
add('Half-range expansion(반구간 전개): 왼쪽을 어떻게 만들까요?',
c('0&lt;x&lt;L에서 같은 함수라도 두 가지 연장이 가능합니다.',p('Even extension(짝연장)은 fₑ(−x)=f(x)로 y축에 반사합니다. Odd extension(홀연장)은 fₒ(−x)=−f(x)로 반사한 뒤 부호를 바꿉니다. 그 결과를 길이 2L마다 반복하면 각각 cosine series(코사인 급수), sine series(사인 급수)를 얻습니다.')+m(r'a_0=\frac1L\int_0^L f(x)\,dx,\qquad a_n=\frac2L\int_0^L f(x)\cos\frac{n\pi x}{L}\,dx')+m(r'b_n=\frac2L\int_0^L f(x)\sin\frac{n\pi x}{L}\,dx')+p('두 전개는 원래 열린 구간 (0,L)에서 같은 함수를 나타낼 수 있지만 음의 구간과 끝점에서 다른 함수를 만듭니다. 원래 문제의 boundary condition(경계조건)이 어떤 전개를 쓸지 결정하는 경우가 많습니다.'))+
n('주어진 그래프의 오른쪽을 바꾸지 않습니다.',p('오른쪽에 점 (1,2)가 있다면 even extension(짝연장)은 (−1,2)를, odd extension(홀연장)은 (−1,−2)를 새로 만듭니다. 원래 (1,2)는 둘 다 그대로입니다. f(0)≠0이면 홀연장은 원점에서 점프를 만들 수 있고, 사인 급수는 원점에서 0이 됩니다.')))
add('Function approximation(함수 근사) ①: 오차를 하나의 숫자로',
c('점마다 다른 오차를 제곱해 적분합니다.',m(r'F_N(x)=a_0+\sum_{n=1}^{N}[a_n\cos(nx)+b_n\sin(nx)]')+m(r'E_N=\int_{-\pi}^{\pi}[f(x)-F_N(x)]^2\,dx')+p('Squared error(제곱오차)는 음수와 양수 오차가 서로 상쇄되지 않게 합니다. 먼저 (f−F)²=f²−2fF+F²로 전개하고, Fourier coefficient(푸리에 계수)의 정의를 이용합니다.')+m(r'2\int_{-\pi}^{\pi}fF_N\,dx=4\pi a_0^2+2\pi\sum_{n=1}^{N}(a_n^2+b_n^2)')+p('이 페이지의 Eₙ은 구간 전체의 integrated squared error(적분제곱오차)입니다. Mean squared error(평균제곱오차)로 부르려면 구간 길이 2π로 한 번 더 나눕니다.'))+
n('시험 점수 오차를 재는 방식과 같습니다.',p('오차가 +2와 −2일 때 그냥 합치면 0이라 완벽해 보입니다. 제곱해서 더하면 4+4=8이라 실제 틀린 정도가 드러납니다. 함수에서는 각 x의 오차를 똑같이 제곱한 뒤 적분합니다. 숫자 목록이 연속적인 그래프로 바뀌었을 뿐입니다.')))
add('Function approximation(함수 근사) ②: 계수로 남은 오차 구하기',
c('직교성 때문에 교차항이 사라집니다.',m(r'\int_{-\pi}^{\pi}F_N^2\,dx=2\pi a_0^2+\pi\sum_{n=1}^{N}(a_n^2+b_n^2)')+m(r'E_N=\int_{-\pi}^{\pi}f^2\,dx-2\pi a_0^2-\pi\sum_{n=1}^{N}(a_n^2+b_n^2)')+p('제곱합을 전개할 때는 상수×진동, 서로 다른 코사인끼리, 서로 다른 사인끼리, 사인×코사인의 모든 교차항이 생깁니다. 각각의 적분이 0이어서 대각항만 남습니다. Eₙ≥0이어야 하므로 계산 결과가 음수라면 계수나 평균값 규약을 재확인합니다.'))+
c('편집자 보강 · 사각파의 첫 근사 오차',p('k=1인 사각파에서 ∫f²dx=2π입니다. sin x 한 항만 쓰면 b₁=4/π이므로 E=2π−16/π≈1.1902입니다. 평균제곱오차는 E/(2π)≈0.1894입니다. 항을 추가하면 포착한 제곱합이 증가하므로 이 적분 오차는 줄어듭니다.'))+
n('원래 에너지에서 담아낸 에너지를 빼기',p('길이 공식 x²+y²와 비슷하게 orthogonal(직교)한 성분들은 제곱 크기를 더할 수 있습니다. 전체 크기에서 지금까지 선택한 파동들의 크기를 빼면 남은 오차가 됩니다. 최대 높이의 오차가 아니라 전체 제곱오차를 계산한다는 점이 중요합니다.')))
add('Practice Problem 1: half-wave rectifier(반파 정류파)',
c('문제 해석과 좌표 변환',p('한 주기 (−L,L)에서 f(t)=0(−L&lt;t&lt;0), f(t)=E sin(ωt)(0&lt;t&lt;L)이며 2L=2π/ω입니다. 여기의 E는 amplitude(진폭)이며 앞의 오차 Eₙ과 다른 기호입니다. θ=ωt로 놓으면 구간은 (−π,π)가 됩니다.'))+
c('편집자 풀이 · 평균값과 사인 계수',steps([m(r'a_0=\frac{E}{2\pi}\int_0^{\pi}\sin\theta\,d\theta=\frac{E}{\pi}'),m(r'b_n=\frac{E}{\pi}\int_0^{\pi}\sin\theta\sin(n\theta)\,d\theta'),p('사인 직교성을 [0,π]에서 쓰면 n=1일 때만 π/2가 남습니다.')+m(r'b_1=\frac E2,\qquad b_n=0\quad(n\ne1)')]))+
c('편집자 풀이 · 코사인 계수와 예외 처리',p('곱-합 공식 sinθ cos(nθ)=[sin((n+1)θ)+sin((1−n)θ)]/2를 사용합니다. n=1은 분모 1−n을 쓰기 전에 따로 계산합니다.')+m(r'a_1=\frac E\pi\int_0^\pi\sin\theta\cos\theta\,d\theta=0')+m(r'a_n=\frac{E}{\pi}\frac{1+(-1)^n}{1-n^2}\quad(n\ne1)')+m(r'a_{2m}=-\frac{2E}{\pi(4m^2-1)},\quad a_{2m+1}=0')+p('따라서 최종 전개는 다음과 같습니다.')+m(r'f(t)=\frac E\pi+\frac E2\sin(\omega t)-\frac{2E}{\pi}\sum_{m=1}^{\infty}\frac{\cos(2m\omega t)}{4m^2-1}')+p('주기적으로 이은 그래프가 t=0,±L에서 연속이고 값이 0이므로 이 지점의 급수 합도 0입니다. 평균값 E/π가 양수인 것은 반주기 동안 양의 봉우리만 남기기 때문입니다.'))+
n('0인 구간을 먼저 지우면 적분이 절반으로 줄어듭니다.',p('함수의 왼쪽 절반은 높이가 0이므로 어떤 사인·코사인을 곱해도 0입니다. 오른쪽의 E sinθ만 계산하면 됩니다. θ 치환에서 dt=dθ/ω이고, 앞의 1/L=ω/π와 곱해져 1/π가 됩니다. 단순히 t를 θ로 바꾸는 것만으로는 부족하고 작은 길이 dt도 함께 바꿔야 합니다.')+p('n=2를 넣어 보면 a₂=−2E/(3π), n=4에서는 a₄=−2E/(15π)입니다. 기본 사인 한 개와 짝수차 코사인들이 반파 모양을 만듭니다.')),'문제 · 편집자 풀이')
add('원본 p.29: 빈 풀이 페이지',c('원본 보존',p('원본은 배경과 쪽번호만 있는 빈 페이지입니다. 앞의 반파 정류파 문제 해설은 <a href="#slide-28">p.28 풀이</a>에 함께 수록했습니다.'),'quiet-card'),'빈 풀이 페이지')
add('Practice Problem 2: sawtooth wave(톱니파)',
c('평균값과 홀함수를 분리합니다.',p('문제는 f(x)=x+π, −π&lt;x&lt;π의 주기 2π 전개입니다. x는 odd function(홀함수), π는 constant(상수)이므로 a₀=π, aₙ=0입니다. f 자체를 홀함수라고 하면 평균값을 놓칩니다.'))+
c('편집자 풀이 · integration by parts(부분적분)',steps([m(r'b_n=\frac2\pi\int_0^\pi x\sin(nx)\,dx'),p('u=x, dv=sin(nx)dx로 선택하면 du=dx, v=−cos(nx)/n입니다.')+m(r'\int x\sin(nx)\,dx=-\frac{x\cos(nx)}n+\frac{\sin(nx)}{n^2}'),p('0과 π를 대입합니다. sin(nπ)=0, cos(nπ)=(−1)ⁿ을 사용합니다.')+m(r'b_n=\frac2\pi\left(-\frac{\pi(-1)^n}{n}\right)=\frac{2(-1)^{n+1}}n'),m(r'f(x)=\pi+2\sum_{n=1}^{\infty}\frac{(-1)^{n+1}}n\sin(nx),\quad -\pi<x<\pi')])+p('주기 경계 x=±π에서는 왼쪽 2π, 오른쪽 0의 평균 π로 수렴합니다. x=0에서도 급수는 π이며 원래 f(0)=π와 일치합니다.'))+
n('부분적분을 왜 사용하나요?',p('x와 sin(nx)를 곱한 적분은 기본 적분표에 바로 없지만, x를 미분하면 1로 단순해집니다. Product rule(곱의 미분법) (uv)′=u′v+uv′를 적분해 정리한 ∫u dv=uv−∫v du가 integration by parts(부분적분)입니다. 이 선택은 “다항식을 미분해 차수를 내린다”는 전략입니다.')+p('n=1,2,3의 계수는 2,−1,2/3입니다. 따라서 π+2sin x−sin 2x+(2/3)sin 3x+…입니다.')),'문제 · 편집자 풀이')
add('원본 p.31: 빈 풀이 페이지',c('원본 보존',p('원본의 빈 풀이 페이지입니다. 톱니파의 계수와 끝점 수렴은 <a href="#slide-30">p.30 풀이</a>에 정리했습니다.'),'quiet-card'),'빈 풀이 페이지')
add('Practice Problem 3: triangular pulse(삼각 펄스)의 짝연장·홀연장',
c('원래 구간의 함수부터 읽습니다.',m(r'f(x)=\begin{cases}\dfrac{2k}{L}x&0<x<L/2\\[3pt]\dfrac{2k}{L}(L-x)&L/2<x<L\end{cases}')+p('0에서 시작해 x=L/2에서 높이 k에 도달하고 x=L에서 다시 0으로 내려옵니다. 꼭짓점에는 f(L/2)=k로 연속적인 값을 붙일 수 있습니다. 원문이 요구하는 것은 even extension(짝연장)과 odd extension(홀연장)입니다.'))+
c('편집자 풀이 · 두 연장을 식으로 완성합니다.',m(r'f_e(x)=\begin{cases}\dfrac{2k}{L}|x|&|x|\le L/2\\[3pt]\dfrac{2k}{L}(L-|x|)&L/2<|x|\le L\end{cases}')+m(r'f_o(x)=\operatorname{sgn}(x)f_e(x),\qquad f_o(0)=0')+m(r'f_e(x+2L)=f_e(x),\qquad f_o(x+2L)=f_o(x)')+p('짝연장은 왼쪽도 위로 솟는 삼각형, 홀연장은 왼쪽이 아래로 내려가는 삼각형입니다. 두 함수 모두 0,±L에서 0으로 연속입니다. 주기 2L로 연장했지만, 짝연장은 이 예제에서 더 작은 기본주기 L도 갖습니다.'))+
c('편집자 보강 · 반구간 cosine series(코사인 급수)',p('원문 요구에서 한 걸음 더 나아가 계수까지 계산합니다. θ=πx/L로 바꾸고 꼭짓점 π/2에서 적분을 나눕니다.')+m(r'a_0=\frac1L\cdot\frac12 Lk=\frac k2')+m(r'a_n=\frac{4k}{\pi^2}\left[\int_0^{\pi/2}\theta\cos(n\theta)\,d\theta+\int_{\pi/2}^{\pi}(\pi-\theta)\cos(n\theta)\,d\theta\right]')+m(r'a_n=\frac{4k}{n^2\pi^2}\left[2\cos\frac{n\pi}{2}-1-(-1)^n\right]')+p('사용한 원시함수는 θsin(nθ)/n+cos(nθ)/n²와 (π−θ)sin(nθ)/n−cos(nθ)/n²입니다. 두 경계의 sin 항은 합할 때 상쇄됩니다.')+m(r'f_e(x)=\frac k2-\frac{4k}{\pi^2}\sum_{j=0}^{\infty}\frac{\cos(2(2j+1)\pi x/L)}{(2j+1)^2}'))+
c('편집자 보강 · 반구간 sine series(사인 급수)',m(r'b_n=\frac{4k}{\pi^2}\left[\int_0^{\pi/2}\theta\sin(n\theta)\,d\theta+\int_{\pi/2}^{\pi}(\pi-\theta)\sin(n\theta)\,d\theta\right]')+p('원시함수는 −θcos(nθ)/n+sin(nθ)/n²와 −(π−θ)cos(nθ)/n−sin(nθ)/n²입니다. 경계에서 cos 항이 상쇄되고 sin 항이 두 배 남습니다.')+m(r'b_n=\frac{8k}{n^2\pi^2}\sin\frac{n\pi}{2}')+m(r'f_o(x)=\frac{8k}{\pi^2}\sum_{j=0}^{\infty}\frac{(-1)^j\sin((2j+1)\pi x/L)}{(2j+1)^2}'))+
n('실제 좌표로 좌우 대칭을 확인합니다.',p('L=2, k=1이면 오른쪽 꼭짓점은 (1,1)입니다. Even extension(짝연장)은 (−1,1)을, odd extension(홀연장)은 (−1,−1)을 만듭니다. 왼쪽에서 x에 음수를 직접 넣어 원래 첫 식을 계속 쓰면 홀연장 일부가 될 뿐, 짝연장까지 자동으로 생기는 것은 아닙니다.')+p('구간을 나누는 기준은 꼭짓점입니다. 직선의 기울기가 바뀌므로 0부터 L까지 하나의 식으로 적분할 수 없습니다. 두 삼각형의 모양이 맞는지 먼저 보고 계수를 계산하십시오.')),'문제 · 편집자 풀이')
add('원본 p.33: 빈 풀이 페이지',c('원본 보존',p('원본의 빈 풀이 페이지입니다. 짝연장·홀연장의 식과 추가 급수 풀이는 <a href="#slide-32">p.32 풀이</a>에 함께 두었습니다.'),'quiet-card'),'빈 풀이 페이지')
add('Weighted inner product(가중 내적)와 norm(노름)',
c('기준 함수를 바꿀 때 내적의 무게도 바뀔 수 있습니다.',m(r'\langle f,g\rangle_r=\int_a^b r(x)f(x)g(x)\,dx,\qquad r(x)>0')+m(r'\|f\|_r=\sqrt{\langle f,f\rangle_r}=\sqrt{\int_a^b r(x)f(x)^2\,dx}')+p('Orthogonal(직교)은 서로 다른 함수의 내적이 0인 성질입니다. Orthonormal(정규직교)은 여기에 각 함수의 norm(노름)이 1이라는 조건을 더한 것입니다. δₘₙ은 번호가 같으면 1, 다르면 0인 Kronecker delta(크로네커 델타)입니다.')+m(r'\langle y_m,y_n\rangle_r=\delta_{mn}')+p('여기서는 실수 함수를 사용합니다. 복소 함수까지 확장하면 내적의 한쪽 함수에 complex conjugate(켤레복소수)를 취하고, 제곱은 절댓값 제곱으로 바꿉니다.'))+
n('가중 평균과 길이 공식에서 출발하기',p('성적에서 시험은 70%, 과제는 30%를 반영하듯 weight function(가중함수) r(x)는 위치별 비중을 정합니다. 어떤 함수가 서로 직교하는지는 이 비중과 적분 구간을 함께 정해야 판단할 수 있습니다.')+p('평면 벡터 (3,4)의 길이가 √(3²+4²)=5인 것처럼, 함수의 norm(노름)은 제곱을 적분한 뒤 루트를 씌웁니다. 제곱한 크기와 길이 자체를 혼동하면 정규화 계수가 틀립니다.')))
add('Normalization(정규화): 사인 함수를 길이 1로',
c('sin(mx)의 노름은 √π입니다.',m(r'\|\sin(mx)\|^2=\int_{-\pi}^{\pi}\sin^2(mx)\,dx=\pi\quad(m\ge1)')+m(r'\phi_m(x)=\frac{\sin(mx)}{\sqrt\pi},\qquad\int_{-\pi}^{\pi}\phi_m(x)^2\,dx=1')+p('같은 사인 함수라도 [0,π]에서는 노름 제곱이 π/2이므로 정규화는 √(2/π)sin(mx)입니다. 구간 없이 정규화 계수를 외우면 안 됩니다.'))+
correction('원본 중간 줄의 sin²(mx)=(1+cos(2mx))/2는 부호가 틀렸습니다. 올바른 식은 (1−cos(2mx))/2입니다. 한 주기 코사인 적분이 0이라 최종 π와 정규화 식은 맞습니다.')+
n('π가 아니라 √π로 나누는 이유',p('함수에 상수 c를 곱하면 제곱적분은 c²배가 됩니다. 따라서 π를 1로 만들려면 c²π=1, 즉 c=1/√π로 정합니다. Normalization(정규화)은 모양을 바꾸는 것이 아니라 세로 크기만 조절하는 작업입니다.')))
add('Sturm–Liouville problem(스튀름–리우빌 문제): 경계가 허용하는 파동',
c('미분방정식과 두 경계조건을 동시에 만족해야 합니다.',m(r'[p(x)y\prime(x)]\prime+[q(x)+\lambda r(x)]y(x)=0')+m(r'k_1y(a)+k_2y\prime(a)=0,\qquad \ell_1y(b)+\ell_2y\prime(b)=0')+p('y=0은 항상 만족하는 trivial solution(자명해)입니다. 이를 제외한 nontrivial solution(비자명해)이 존재하게 하는 λ가 eigenvalue(고유값), 그때의 함수 y가 eigenfunction(고유함수)입니다. 각 경계에서 계수 두 개가 동시에 0이면 안 됩니다.')+p('Regular problem(정칙 문제)의 전형적 조건은 유한 구간, 연속인 계수, p&gt;0와 r&gt;0, self-adjoint boundary conditions(자기수반 경계조건)입니다. 끝점에서 p가 0이 되거나 구간이 무한이면 singular problem(특이 문제)이 될 수 있어 별도 끝점 조건을 검토합니다.')+p('원본의 periodic boundary conditions(주기 경계조건) y(a)=y(b), y′(a)=y′(b)는 p(a)=p(b)인 경우와 함께 이해합니다. 일반 p에서는 p(a)y′(a)=p(b)y′(b)처럼 경계항을 없애는 조건이 필요합니다.'))+
n('새 기호를 하나씩 번역하기',p('y′는 그래프의 기울기, y″는 기울기의 변화율입니다. [py′]′는 p와 y′를 곱한 전체를 미분한다는 뜻이며 p y″만 뜻하지 않습니다. λ는 함수를 찾으며 함께 결정할 미지의 숫자입니다.')+p('양 끝을 묶은 줄을 떠올리면 boundary condition(경계조건)은 “양 끝에서 변위가 0”이라는 제한입니다. 아무 파동이나 넣으면 끝점이 흔들려 탈락합니다. 끝이 고정된 채 들어맞는 파동 모양과 그 숫자만 남기는 것이 eigenvalue problem(고유값 문제)입니다.')))
add('서로 다른 eigenvalue(고유값)의 함수는 왜 직교할까요?',
c('편집자 보강 · 직교성의 짧은 증명',p('같은 자기수반 문제의 두 해 yₘ,yₙ을 택합니다. m번째 방정식에 yₙ, n번째 방정식에 yₘ을 곱해서 빼고 적분합니다. q항은 상쇄되고 도함수 항은 경계값으로 모입니다.')+m(r'\left[p(y_ny_m\prime-y_my_n\prime)\right]_a^b+(\lambda_m-\lambda_n)\int_a^b r\,y_my_n\,dx=0')+p('허용된 경계조건으로 첫 항이 0입니다. λₘ≠λₙ이면 두 번째 적분이 0이어야 하므로 orthogonality(직교성)가 나옵니다. 단순히 계수가 연속이라는 조건만으로는 충분하지 않습니다.'))+
c('Legendre equation(르장드르 방정식)을 같은 꼴로 바꾸기',m(r'(1-x^2)y\prime\prime-2xy\prime+n(n+1)y=0')+m(r'[(1-x^2)y\prime]\prime+n(n+1)y=0')+p('곱의 미분법으로 [(1−x²)y′]′=(1−x²)y″−2xy′입니다. 따라서 p=1−x², q=0, r=1, λ=n(n+1)로 읽습니다.'))+
n('같은 식에서 무엇을 빼는지 보기',p('q yₘ yₙ과 q yₙ yₘ은 같아서 사라집니다. λ항은 λₘr yₘyₙ−λₙr yₘyₙ=(λₘ−λₙ)r yₘyₙ이 됩니다. 고등학교의 공통인수 묶기를 그대로 쓰는 단계입니다. 어려운 부분은 경계항이 0인 이유이며, 이것을 보장하려고 boundary condition(경계조건)을 정확히 정합니다.')))
add('Legendre polynomial(르장드르 다항식): 사인 대신 다항식',
c('표준 번호는 0차부터 시작합니다.',m(r'P_0=1,\quad P_1=x,\quad P_2=\frac{3x^2-1}{2},\quad P_3=\frac{5x^3-3x}{2}')+m(r'\int_{-1}^{1}P_m(x)P_n(x)\,dx=0\quad(m\ne n)')+p('예를 들어 ∫₋₁¹P₀P₁dx=∫₋₁¹x dx=0입니다. P₀와 P₂도 ∫(3x²−1)/2 dx=(3·2/3−2)/2=0입니다. p(±1)=0이므로 이 문제는 singular(특이)하며 끝점에서의 적절한 정칙성 조건을 함께 사용합니다.'))+
correction('원본 p.38은 P₁=1, P₂=x처럼 번호를 한 칸 밀어 씁니다. 뒤의 p.41과 표준 Legendre notation(르장드르 표기)에 맞춰 P₀=1, P₁=x로 통일합니다. 따라서 λₙ=n(n+1), n=0,1,2,…입니다.')+
n('x²를 기준 다항식으로 조립해 보기',p('P₂=(3x²−1)/2를 정리하면 x²=(1/3)P₀+(2/3)P₂입니다. 이것도 하나의 generalized Fourier expansion(일반화된 푸리에 전개)입니다. Fourier라는 이름이 붙었다고 반드시 사인·코사인만 쓰는 것은 아닙니다.')))
add('Bessel equation(베셀 방정식): 가중함수가 x가 됩니다.',
c('x로 나누고 곱의 미분으로 묶습니다.',m(r'x^2y\prime\prime+xy\prime+(k^2x^2-\nu^2)y=0')+m(r'[xy\prime]\prime+\left(\lambda x-\frac{\nu^2}{x}\right)y=0,\qquad\lambda=k^2')+p('p=x, q=−ν²/x, r=x입니다. 여기서는 원본의 차수 n을 ν로 바꾸어, 서로 다른 고유함수의 번호 j와 구별합니다. x=0은 특이 끝점이므로 위의 나눗셈은 x&gt;0에서 시행합니다.')+p('원점에서 정칙인 해를 선택하면 Bessel function of the first kind(제1종 베셀 함수) Jᵥ(kx)가 남습니다. y(a)=0은 Jᵥ(ka)=0을 요구합니다. 양의 영점을 jᵥ,ⱼ라 하면 kⱼ=jᵥ,ⱼ/a이고 λⱼ=(jᵥ,ⱼ/a)²입니다.')+m(r'\int_0^a x\,J_\nu(k_jx)J_\nu(k_\ell x)\,dx=0\quad(j\ne\ell)')+p('같은 차수 ν와 같은 경계조건에 속한 서로 다른 영점의 함수들끼리의 직교성입니다. 임의의 k를 골라도 모두 직교한다는 뜻은 아닙니다.'))+
n('지금은 베셀 함수를 처음부터 계산할 필요가 없습니다.',p('Jᵥ는 이 미분방정식에 맞춰 정의한 특별한 기본 함수의 이름입니다. sin이 y″+y=0에 들어맞는 함수인 것과 비슷합니다. 여기서 익힐 핵심은 “기준 함수가 바뀌면 weight function(가중함수)도 바뀐다”는 연결입니다. 이 경우 inner product(내적)를 계산할 때 x를 빠뜨리면 직교성이 깨집니다.')))
add('Generalized Fourier series(일반화된 푸리에 급수)',
c('직교기저로의 정사영이라는 처음 원리로 돌아옵니다.',m(r'f\sim\sum_{m=0}^{\infty}a_my_m,\qquad a_m=\frac{\langle f,y_m\rangle_r}{\|y_m\|_r^2}')+m(r'a_m=\frac{\int_a^b r(x)f(x)y_m(x)\,dx}{\int_a^b r(x)y_m(x)^2\,dx}')+p('Orthonormal(정규직교) 함수이면 분모가 1입니다. Orthogonal(직교)이기만 하면 분모를 반드시 유지합니다. Sturm–Liouville의 고유함수를 쓰는 경우 eigenfunction expansion(고유함수 전개)이라고 부릅니다.')+p('급수가 원래 함수를 복원하는지에는 completeness(완비성)와 적절한 함수 공간의 조건이 필요합니다. 계수 계산과 수렴 보장은 다른 단계입니다.'))+
n('모든 계수 공식의 공통 문장',p('“목표 함수와 기준 함수를 곱해 더한 뒤, 기준 함수 자신의 제곱 크기로 나눈다.” 벡터에서는 더하기, 함수에서는 integration(적분)을 사용합니다. 사인·코사인, Legendre polynomial(르장드르 다항식), Bessel function(베셀 함수)이 모두 이 문장 안에 들어옵니다.')))
add('예제: sin(πx)의 Fourier–Legendre series(푸리에–르장드르 급수)',
c('노름과 홀짝성부터 확인합니다.',m(r'\|P_m\|^2=\frac{2}{2m+1},\qquad a_m=\frac{2m+1}{2}\int_{-1}^{1}\sin(\pi x)P_m(x)\,dx')+p('sin(πx)는 odd function(홀함수)입니다. Pₘ은 m이 짝수이면 짝함수, 홀수이면 홀함수이므로 모든 짝수 계수는 0입니다. 원본의 합 하한 m=1과 우변의 a₀P₀가 충돌하므로 일반 전개는 m=0부터 시작합니다. 이 예제에서는 a₀=0입니다.'))+
c('편집자 풀이 · 첫 두 비영 계수',p('P₁=x이므로 부분적분 한 번으로 a₁을 계산합니다.')+m(r'I_1=\int_{-1}^{1}x\sin(\pi x)\,dx=\frac2\pi,\qquad a_1=\frac32I_1=\frac3\pi')+p('P₃=(5x³−3x)/2를 사용하려면 I₃도 필요합니다. 부분적분을 두 번 추가하면 다음과 같습니다.')+m(r'I_3=\int_{-1}^{1}x^3\sin(\pi x)\,dx=\frac2\pi-\frac{12}{\pi^3}')+m(r'a_3=\frac74(5I_3-3I_1)=\frac7\pi-\frac{105}{\pi^3}')+m(r'F_3(x)=\frac3\pi P_1(x)+\left(\frac7\pi-\frac{105}{\pi^3}\right)P_3(x)')+p('a₁≈0.95493, a₃≈−1.15824입니다. 계수의 절댓값이 1보다 크더라도 문제가 아닙니다. 기준 다항식이 길이 1로 정규화되어 있지 않기 때문입니다.'))+
n('왜 sin(πx)를 사인 하나로 끝내지 않나요?',p('삼각함수를 기준으로 고르면 sin(πx)는 한 항으로 끝납니다. 하지만 지금 예제의 목적은 polynomial basis(다항식 기저)로 같은 곡선을 근사하는 연습입니다. 같은 벡터도 좌표축을 바꾸면 좌표 숫자가 바뀌듯, 함수도 기준을 바꾸면 필요한 계수가 달라집니다.')),'예제 · 편집자 풀이')
add('MATLAB 예제 읽기: 1차·3차·5차 근사의 의미',
c('코드의 각 부분을 수식과 대응시킵니다.',p('legendreP(n,x)는 Pₙ(x)를 만들고, legpol(n)은 [(2n+1)/2]∫₋₁¹sin(πx)Pₙ(x)dx를 계산합니다. subs는 다항식에 실제 좌표를 대입하고, double은 기호식을 수치로 바꿉니다. 누적합 s=s+f가 partial sum(부분합)입니다.')+p('원본 주석의 sin(x)는 실제 계산 함수 sin(πx)와 다릅니다. 코드의 적분 구간은 [−1,1]이지만 시각화 좌표 t=0:0.05:1은 오른쪽 절반만 보여줍니다. 짝수 계수와 a₀가 0이므로 n=1부터 반복해도 이 예제에서는 같습니다.'))+
c('편집자 보강 · 5차 계수까지 확인',m(r'P_5(x)=\frac{63x^5-70x^3+15x}{8}')+m(r'I_5=\frac2\pi-\frac{40}{\pi^3}+\frac{240}{\pi^5}')+m(r'a_5=\frac{11}{16}(63I_5-70I_3+15I_1)=\frac{11}{\pi}-\frac{1155}{\pi^3}+\frac{10395}{\pi^5}')+p('a₅≈0.21929입니다. F₅= a₁P₁+a₃P₃+a₅P₅이며, 5차 근사란 다항식의 최대 차수가 5라는 뜻입니다. 0이 아닌 항은 3개입니다.'))+
n('프로그램을 몰라도 반복문의 계산을 읽을 수 있습니다.',p('처음 s=0으로 시작합니다. n=1에서 a₁P₁을 더하고, n=2에서는 계수 0이므로 변화가 없습니다. n=3에서 a₃P₃, n=5에서 a₅P₅를 더합니다. x 대신 t라는 이름을 써도 여전히 그래프를 찍는 입력 좌표이며, 코드의 t가 항상 물리적 시간이라는 뜻은 아닙니다.')))
add('Mean-square convergence(평균제곱 수렴)와 Bessel’s inequality(베셀 부등식)',
c('전체 오차가 0으로 가는 수렴을 정의합니다.',m(r'\|f_k-f\|_r^2=\int_a^b r(x)[f_k(x)-f(x)]^2\,dx\longrightarrow0')+p('이 정의는 각각의 x에서 값이 수렴한다는 pointwise convergence(점별 수렴)와 다릅니다. 이 페이지의 제곱 계수 부등식은 orthonormal(정규직교) 함수계에 대한 것입니다.')+m(r'\sum_{m=0}^{k}a_m^2\le\|f\|_r^2\qquad\text{(orthonormal set)}')+m(r'\sum_{m=0}^{k}a_m^2\|y_m\|_r^2\le\|f\|_r^2\qquad\text{(orthogonal set)}')+p('Bessel’s inequality(베셀 부등식)는 Bessel function(베셀 함수)을 사용할 때만 성립하는 식이 아닙니다. 이름은 같지만 적용 범위는 일반적인 직교 전개입니다.'))+
n('점 하나와 전체 넓이를 구별하기',p('함수를 단 한 점에서 바꾸어도 제곱오차의 적분은 바뀌지 않습니다. 따라서 mean-square convergence(평균제곱 수렴)만으로 그 점의 값까지 같다고 결론 내릴 수 없습니다. 부등식은 “지금까지 뽑아낸 성분의 에너지가 원래 전체보다 클 수 없다”는 뜻입니다.')))
add('Bessel’s inequality(베셀 부등식) 증명 ①: 두 적분',
c('정규직교성을 적용하기 전에는 모든 항을 적습니다.',m(r'f_k=\sum_{m=0}^{k}a_my_m,\qquad a_m=\langle f,y_m\rangle_r')+m(r'\|f_k\|_r^2=\sum_{m=0}^{k}\sum_{n=0}^{k}a_ma_n\langle y_m,y_n\rangle_r=\sum_{m=0}^{k}a_m^2')+m(r'\langle f,f_k\rangle_r=\sum_{m=0}^{k}a_m\langle f,y_m\rangle_r=\sum_{m=0}^{k}a_m^2')+p('첫 식에서 m≠n인 항은 0, m=n인 항은 내적 1입니다. 두 번째 식에서는 계수의 정의를 사용합니다. 같은 제곱합이 서로 다른 두 계산에서 나온다는 점이 다음 페이지의 핵심입니다.'))+
correction('원본의 일부 적분 범위 −π,π는 이 일반화된 증명에서는 a,b로 통일합니다. ||yₘ||²를 1로 없애는 단계에는 정규직교 조건이 필요합니다.')+
n('두 항만 펼치면 이중합이 보입니다.',p('두 항 부분합 f₁=a₀y₀+a₁y₁이라 놓으면 제곱은 a₀²y₀²+2a₀a₁y₀y₁+a₁²y₁²입니다. 가운데 항의 적분은 0이고 양 끝의 y 제곱 적분은 각각 1입니다. 그래서 a₀²+a₁²만 남습니다. 기호가 많아졌을 뿐 완전제곱식 전개입니다.')))
add('Bessel’s inequality(베셀 부등식) 증명 ②: 오차는 음수가 아닙니다.',
c('제곱 노름의 비음수성을 사용합니다.',m(r'0\le\|f-f_k\|_r^2=\|f\|_r^2-2\langle f,f_k\rangle_r+\|f_k\|_r^2')+m(r'\|f-f_k\|_r^2=\|f\|_r^2-\sum_{m=0}^{k}a_m^2')+m(r'\sum_{m=0}^{\infty}a_m^2\le\|f\|_r^2')+p('제곱 계수의 부분합은 항을 더할수록 감소하지 않고 전체 노름 제곱으로 위에서 제한됩니다. 따라서 이 숫자 부분합은 수렴합니다. 이것만으로 함수 근사가 원래 f로 수렴한다고 결론 내리지는 못합니다. 남아 있는 오차가 양수일 수도 있습니다.'))+
n('상한이 있다는 것과 목적지에 도착한다는 것은 다릅니다.',p('1/2+1/4+1/8+…은 계속 증가하지만 1을 넘지 않습니다. “계수 에너지의 합이 어떤 값으로 모인다”는 사실과 “그 값이 원함수의 전체 에너지와 같다”는 사실은 다른 주장입니다. 두 번째를 보장하는 개념이 다음 페이지의 completeness(완비성)입니다.')))
add('Completeness(완비성)와 Parseval’s equality(파르세발 등식)',
c('완비한 기저이면 빠진 성분이 없습니다.',p('Complete orthonormal set(완비 정규직교 함수계)은 해당 함수 공간의 어떤 f도 norm(노름) 오차를 원하는 만큼 작게 하여 근사할 수 있는 함수계입니다. 계수가 정사영으로 정해졌다면 극한 오차가 0일 때 Bessel inequality(베셀 부등식)는 Parseval equality(파르세발 등식)가 됩니다.')+m(r'\forall\varepsilon>0,\ \exists k:\ \left\|f-\sum_{m=0}^{k}a_my_m\right\|_r<\varepsilon')+m(r'\sum_{m=0}^{\infty}a_m^2=\|f\|_r^2')+p('불완전한 함수계여도 특정 f가 그 함수계의 닫힌 생성공간 안에 들어 있으면 그 f에 대해서는 등식이 가능합니다. “기저가 불완전하다”와 “모든 f에 항상 엄격한 부등호”는 동치가 아닙니다.'))+
c('편집자 보강 · 원래 삼각급수 규약으로 쓰기',m(r'\int_{-\pi}^{\pi}f(x)^2\,dx=2\pi a_0^2+\pi\sum_{n=1}^{\infty}(a_n^2+b_n^2)')+p('사인·코사인 원형은 정규화되지 않았으므로 2π와 π가 붙습니다. 원본과 이 노트는 상수항 a₀ 규약을 사용합니다. a₀/2 규약의 교재 식을 그대로 베끼면 첫 항이 틀립니다.'))+
n('좌표축 하나가 빠진 평면',p('평면에서 수평축만 허용하면 (3,0)은 완벽히 표현하지만 (3,2)는 수직 성분 2가 남습니다. 아무리 수평 성분을 더해도 수직 성분을 만들 수 없습니다. Completeness(완비성)는 필요한 방향이 모두 준비되어 있다는 뜻입니다. 함수에서도 빠진 방향의 에너지가 잔차로 남습니다.')))
add('Practice Problem: y″+λy=0의 eigenvalue(고유값)와 eigenfunction(고유함수)',
c('문제의 조건',m(r'y\prime\prime+\lambda y=0,\qquad y(0)=0,\quad y(\pi)=0')+p('구할 것은 0이 아닌 해를 허용하는 λ와 그때의 함수입니다. λ의 부호에 따라 해의 모양이 달라지므로 세 경우를 모두 확인합니다.'))+
c('편집자 풀이 · λ=0',m(r'y\prime\prime=0\ \Rightarrow\ y=Ax+B')+p('y(0)=0에서 B=0, y(π)=0에서 Aπ=0이므로 A=0입니다. y≡0만 남아 λ=0은 eigenvalue(고유값)가 아닙니다.'))+
c('편집자 풀이 · λ&lt;0',p('λ=−μ², μ&gt;0이라 놓으면 해는 지수함수의 조합입니다.')+m(r'y=A\cosh(\mu x)+B\sinh(\mu x)')+p('y(0)=0에서 A=0입니다. y(π)=B sinh(μπ)=0이고 μ&gt;0에서 sinh(μπ)&gt;0이므로 B=0입니다. 음의 λ에도 비자명해가 없습니다.'))+
c('편집자 풀이 · λ&gt;0',p('λ=μ², μ&gt;0이라 놓으면 진동해를 얻습니다.')+m(r'y=A\cos(\mu x)+B\sin(\mu x)')+p('y(0)=0에서 A=0입니다. 비자명해를 위해 B≠0이어야 하므로 sin(μπ)=0이어야 합니다. 따라서 μ=n, n=1,2,3,…입니다.')+m(r'\boxed{\lambda_n=n^2,\qquad y_n(x)=B\sin(nx),\quad B\ne0,\quad n=1,2,\ldots}')+p('직접 두 번 미분하면 yₙ″=−n²yₙ이고 두 끝점에서도 0이 됩니다. Normalized eigenfunction(정규화된 고유함수)을 원하면 아래처럼 쓸 수 있습니다.')+m(r'\phi_n(x)=\sqrt{\frac2\pi}\sin(nx),\qquad\int_0^\pi\phi_n(x)^2\,dx=1'))+
n('미분방정식 해 모양을 직접 검사하기',p('λ&gt;0일 때 sin(μx)를 두 번 미분하면 −μ²sin(μx)가 됩니다. 따라서 λ=μ²이면 y″+λy=0이 맞습니다. λ&lt;0일 때에는 지수함수를 두 번 미분하면 양의 μ²가 곱해지므로 exp(μx), exp(−μx)의 조합을 사용합니다. exp(z)는 e의 z제곱입니다. cosh z=(eᶻ+e⁻ᶻ)/2, sinh z=(eᶻ−e⁻ᶻ)/2는 이 조합의 이름입니다.')+p('sin(μπ)=0은 고등학교 삼각함수에서 각도가 π의 정수배여야 한다는 조건입니다. μ=0은 이미 자명해만 남는 경우이고, 음의 n은 양의 n의 함수에 −1을 곱한 같은 방향이므로 n=1,2,3,…만 적습니다. 이 문제의 공간 구간은 [0,π]라서 정규화 계수가 1/√π가 아니라 √(2/π)입니다.')),'문제 · 편집자 풀이')
add('원본 p.48: 마지막 빈 풀이 페이지',c('원본 보존',p('원본은 빈 풀이 페이지로 끝납니다. 마지막 고유값 문제의 세 경우 해설은 <a href="#slide-47">p.47 풀이</a>에 수록했습니다. 아래에서 시험 영어 표현과 용어, 원본 교정 기록을 이어서 확인할 수 있습니다.'),'quiet-card'),'빈 풀이 페이지')

assert len(PAGES)==48, len(PAGES)
